window.bookingCopy=bookingCopy;
const appointmentForm=document.querySelector('#appointment-form');
if(appointmentForm){
 let feedbackKey='',busy=false,submissionId=crypto.randomUUID();const feedback=document.querySelector('#booking-feedback');
 function renderBooking(){const c=bookingCopy[document.documentElement.lang]||bookingCopy.fr;document.querySelector('#appointment-title').textContent=c.title;document.querySelectorAll('[data-book]').forEach(e=>e.textContent=c[e.dataset.book]);[...appointmentForm.elements.pet.options].forEach((o,i)=>o.textContent=c.pets[i]);[...appointmentForm.elements.service.options].forEach((o,i)=>o.textContent=c.services[i]);[...appointmentForm.elements.preferred_time.options].forEach((o,i)=>o.textContent=c.times[i]);feedback.textContent=feedbackKey?c[feedbackKey]:'';appointmentForm.querySelector('[type=submit]').textContent=busy?c.sending:c.submit;document.querySelector('.admin-link').textContent=c.admin;}
 window.prefillAppointment=(pet,service)=>{appointmentForm.elements.pet.value=pet;appointmentForm.elements.service.value=service;document.querySelector('#appointment').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});appointmentForm.elements.name.focus({preventScroll:true})};
 window.addEventListener('scar-language',renderBooking);renderBooking();
 const now=new Date();const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Brussels',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);const today=['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-');appointmentForm.elements.preferred_date.min=today;const max=new Date(now.getTime()+365*86400000);appointmentForm.elements.preferred_date.max=max.toISOString().slice(0,10);
 appointmentForm.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;if(!appointmentForm.reportValidity())return;const data=Object.fromEntries(new FormData(appointmentForm));data.id=submissionId;data.language=document.documentElement.lang;busy=true;feedbackKey='';appointmentForm.querySelector('[type=submit]').disabled=true;renderBooking();
  try{const res=await fetch('/api/requests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!res.ok){feedbackKey=res.status===400?'invalid':'error';feedback.dataset.state='error'}else{feedbackKey='success';feedback.dataset.state='success';appointmentForm.reset();submissionId=crypto.randomUUID()}}
  catch{feedbackKey='error';feedback.dataset.state='error'}finally{busy=false;appointmentForm.querySelector('[type=submit]').disabled=false;renderBooking();feedback.focus({preventScroll:true})}
 });
}
